package com.iingstd.photoprint;
import android.app.*;import android.os.*;import android.widget.*;import android.graphics.Color;import java.net.*;import java.io.*;
public class MainActivity extends Activity {
 android.net.nsd.NsdManager nsd; android.net.nsd.NsdManager.DiscoveryListener listener;
 boolean resolving;
 EditText printUri; TextView printStatus; Spinner paper,quality,color,type,margin,scaling; EditText copies,range;
 @Override protected void onActivityResult(int request,int result,android.content.Intent data){super.onActivityResult(request,result,data);if(request!=42||result!=RESULT_OK||data==null||data.getData()==null)return;android.net.Uri file=data.getData();String mime=getContentResolver().getType(file);if(!"application/pdf".equals(mime)&&!"image/jpeg".equals(mime)){printStatus.setText("Format belum didukung");return;}String address=printUri.getText().toString().trim();String[] media={"iso_a4_210x297mm","custom_f4_210x330mm","na_legal_8.5x14in","na_index-4x6_4x6in"};String selected=media[paper.getSelectedItemPosition()];int qual=new int[]{0,3,4,5}[quality.getSelectedItemPosition()];String col=new String[]{"","color","monochrome"}[color.getSelectedItemPosition()];String typ=new String[]{"","stationery","photographic-glossy","photographic-matte"}[type.getSelectedItemPosition()];int mar=new int[]{-1,0,3,5,10}[margin.getSelectedItemPosition()];String scale=new String[]{"","fit","fill","none"}[scaling.getSelectedItemPosition()];int start=0,end=0;String pages=range.getText().toString().trim();if("application/pdf".equals(mime)&&!pages.isEmpty()){try{String[] parts=pages.split("-", -1);if(parts.length>2)throw new Exception();start=Integer.parseInt(parts[0].trim());end=parts.length==2?Integer.parseInt(parts[1].trim()):start;if(start<1||end<start)throw new Exception();}catch(Exception e){printStatus.setText("Rentang halaman tidak valid. Contoh: 2-5");return;}}final int first=start,last=end;int count;try{count=Integer.parseInt(copies.getText().toString());if(count<1||count>99)throw new Exception();}catch(Exception e){printStatus.setText("Jumlah salinan harus 1–99");return;}final int[] rotation={0,0,0,1,3};AlertDialog confirmation=new AlertDialog.Builder(this).setView(preview(file,mime,first,last,rotation,selected,mar)).setTitle("Preview sebelum cetak").setMessage("Ukuran: "+paper.getSelectedItem()+"\nFormat: "+mime).setNegativeButton("Batal",null).setPositiveButton("Cetak",null).create();confirmation.show();confirmation.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{if(rotation[2]>0){try{passportCells(rotation[2],selected,mar,rotation[3],rotation[4]);}catch(IOException e){Toast.makeText(this,e.getMessage(),Toast.LENGTH_LONG).show();return;}}confirmation.dismiss();printStatus.setText("Mengirim...");new Thread(()->{String msg;try(InputStream in=rotation[2]>0?passportInput(file,rotation[0],rotation[2],selected,mar,rotation[3],rotation[4]):photoInput(file,mime,rotation[0],rotation[1])){if(in==null)throw new IOException("File tidak dapat dibuka");if("application/pdf".equals(mime)){try(android.graphics.pdf.PdfRenderer pdf=new android.graphics.pdf.PdfRenderer(getContentResolver().openFileDescriptor(file,"r"))){if(last>pdf.getPageCount())throw new IOException("Halaman melebihi jumlah PDF: "+pdf.getPageCount());}}msg=Ipp.print(address,rotation[2]>0?"application/pdf":mime,in,selected,qual,col,typ,count,mar,rotation[2]>0?"none":scale,first,last);}catch(Exception e){msg="Gagal: "+e.getMessage();}String finalMsg=msg;runOnUiThread(()->printStatus.setText(finalMsg));}).start();});}

 static float[] paperMm(String media){if(media.equals("custom_f4_210x330mm"))return new float[]{210,330};if(media.equals("na_legal_8.5x14in"))return new float[]{215.9f,355.6f};if(media.equals("na_index-4x6_4x6in"))return new float[]{101.6f,152.4f};return new float[]{210,297};}
 static android.graphics.RectF[] passportCells(int size,String media,int margin,int count,int gap)throws IOException{
 float[] paper=paperMm(media);int w=new int[]{0,20,30,40}[size],h=new int[]{0,30,40,60}[size],m=Math.max(5,margin);
 int cols=(int)Math.floor((paper[0]-2*m+gap)/(w+gap)),rows=(int)Math.floor((paper[1]-2*m+gap)/(h+gap));
 if(count<1||cols<1||rows<1||count>cols*rows)throw new IOException("Maksimum "+Math.max(0,cols*rows)+" foto per lembar");
 android.graphics.RectF[] cells=new android.graphics.RectF[count];for(int i=0;i<count;i++){float x=m+(i%cols)*(w+gap),y=m+(i/cols)*(h+gap);cells[i]=new android.graphics.RectF(x,y,x+w,y+h);}return cells;
 }
 InputStream passportInput(android.net.Uri file,int rotation,int size,String media,int margin,int count,int gap)throws IOException{
 float[] paper=paperMm(media);float unit=72f/25.4f;
 android.graphics.RectF[] cells=passportCells(size,media,margin,count,gap);
 try(InputStream in=photoInput(file,"image/jpeg",rotation,size==2?3:2)){
 android.graphics.Bitmap bitmap=android.graphics.BitmapFactory.decodeStream(in);if(bitmap==null)throw new IOException("Foto tidak dapat dibaca");
 android.graphics.pdf.PdfDocument pdf=new android.graphics.pdf.PdfDocument();
 try{android.graphics.pdf.PdfDocument.Page page=pdf.startPage(new android.graphics.pdf.PdfDocument.PageInfo.Builder(Math.round(paper[0]*unit),Math.round(paper[1]*unit),1).create());android.graphics.Canvas canvas=page.getCanvas();canvas.drawColor(android.graphics.Color.WHITE);for(android.graphics.RectF cell:cells)canvas.drawBitmap(bitmap,null,new android.graphics.RectF(cell.left*unit,cell.top*unit,cell.right*unit,cell.bottom*unit),new android.graphics.Paint(android.graphics.Paint.FILTER_BITMAP_FLAG));pdf.finishPage(page);ByteArrayOutputStream bytes=new ByteArrayOutputStream();pdf.writeTo(bytes);return new ByteArrayInputStream(bytes.toByteArray());}finally{pdf.close();bitmap.recycle();}
 }
 }
 InputStream photoInput(android.net.Uri file,String mime,int rotation,int crop)throws IOException{
 if((rotation==0&&crop==0)||!"image/jpeg".equals(mime))return getContentResolver().openInputStream(file);
 if(android.os.Build.VERSION.SDK_INT<28)throw new IOException("Rotasi memerlukan Android 9");
 android.graphics.Bitmap original=android.graphics.ImageDecoder.decodeBitmap(android.graphics.ImageDecoder.createSource(getContentResolver(),file),(decoder,header,source)->{int w=header.getSize().getWidth(),h=header.getSize().getHeight();double scale=Math.min(1.0,Math.min(4200.0/Math.max(w,h),Math.sqrt(12000000.0/((double)w*h))));decoder.setTargetSize(Math.max(1,(int)(w*scale)),Math.max(1,(int)(h*scale)));decoder.setAllocator(android.graphics.ImageDecoder.ALLOCATOR_SOFTWARE);});
 android.graphics.Bitmap edited=null;try{edited=editBitmap(original,rotation,crop);ByteArrayOutputStream bytes=new ByteArrayOutputStream();if(!edited.compress(android.graphics.Bitmap.CompressFormat.JPEG,95,bytes))throw new IOException("Edit foto gagal");return new ByteArrayInputStream(bytes.toByteArray());}finally{if(edited!=null&&edited!=original)edited.recycle();original.recycle();}
 }
 static android.graphics.Bitmap editBitmap(android.graphics.Bitmap original,int rotation,int crop){
 android.graphics.Matrix matrix=new android.graphics.Matrix();matrix.postRotate(rotation);
 android.graphics.Bitmap rotated=rotation==0?original:android.graphics.Bitmap.createBitmap(original,0,0,original.getWidth(),original.getHeight(),matrix,true);
 if(crop==0)return rotated;
 float ratio=new float[]{0,1f,2f/3,3f/4,4f/6,4f/3,3f/2}[crop];
 int w=rotated.getWidth(),h=rotated.getHeight(),cw=w,ch=h;
 if(w/(float)h>ratio)cw=Math.max(1,Math.round(h*ratio));else ch=Math.max(1,Math.round(w/ratio));
 android.graphics.Bitmap result=android.graphics.Bitmap.createBitmap(rotated,(w-cw)/2,(h-ch)/2,cw,ch);
 if(rotated!=original&&rotated!=result)rotated.recycle();return result;
 }
 android.view.View preview(android.net.Uri file,String mime,int first,int last,int[] rotation,String media,int margin){
 LinearLayout layout=new LinearLayout(this);layout.setOrientation(1);layout.setPadding(16,8,16,8);
 ImageView image=new ImageView(this);image.setScaleType(ImageView.ScaleType.FIT_CENTER);layout.addView(image,new LinearLayout.LayoutParams(-1,(int)(300*getResources().getDisplayMetrics().density)));
 TextView layoutStatus=new TextView(this);layout.addView(layoutStatus);
 final android.graphics.Bitmap[] base={null},shown={null};
 Runnable refresh=()->{if(base[0]==null)return;layoutStatus.setText("");android.graphics.Bitmap edited=editBitmap(base[0],rotation[0],rotation[2]>0?(rotation[2]==2?3:2):rotation[1]);if(rotation[2]>0){try{android.graphics.RectF[] cells=passportCells(rotation[2],media,margin,rotation[3],rotation[4]);layoutStatus.setText(rotation[3]+" foto • jarak "+rotation[4]+" mm • margin minimal "+Math.max(5,margin)+" mm");float[] paper=paperMm(media);float scale=900f/paper[1];android.graphics.Bitmap sheet=android.graphics.Bitmap.createBitmap(Math.round(paper[0]*scale),900,android.graphics.Bitmap.Config.ARGB_8888);android.graphics.Canvas canvas=new android.graphics.Canvas(sheet);canvas.drawColor(android.graphics.Color.WHITE);for(android.graphics.RectF cell:cells)canvas.drawBitmap(edited,null,new android.graphics.RectF(cell.left*scale,cell.top*scale,cell.right*scale,cell.bottom*scale),new android.graphics.Paint(android.graphics.Paint.FILTER_BITMAP_FLAG));if(edited!=base[0])edited.recycle();edited=sheet;}catch(IOException e){if(edited!=base[0])edited.recycle();image.setImageDrawable(null);layoutStatus.setText(e.getMessage()+" — kurangi jumlah atau jarak foto.");return;}}image.setImageBitmap(edited);if(shown[0]!=null&&shown[0]!=base[0]&&shown[0]!=edited)shown[0].recycle();shown[0]=edited;};
 if("image/jpeg".equals(mime)&&android.os.Build.VERSION.SDK_INT>=28){Button rotate=new Button(this);rotate.setText("Putar 90°");layout.addView(rotate);rotate.setOnClickListener(v->{rotation[0]=(rotation[0]+90)%360;refresh.run();rotate.setText("Putar 90° ("+rotation[0]+"°)");});Spinner crop=option(layout,"Crop tengah (rasio)",new String[]{"Asli","1:1","2:3","3:4","4:6","4:3","3:2"});crop.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onItemSelected(android.widget.AdapterView<?> parent,android.view.View view,int position,long id){rotation[1]=position;refresh.run();}public void onNothingSelected(android.widget.AdapterView<?> parent){}});Spinner size=option(layout,"Pas foto (PDF ukuran asli, kiri atas)",new String[]{"Nonaktif","2 x 3 cm","3 x 4 cm","4 x 6 cm"});size.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onItemSelected(android.widget.AdapterView<?> parent,android.view.View view,int position,long id){rotation[2]=position;crop.setEnabled(position==0);refresh.run();}public void onNothingSelected(android.widget.AdapterView<?> parent){}});Spinner qty=option(layout,"Jumlah pas foto per lembar",new String[]{"1","2","4","6","8","12","16","20"});qty.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onItemSelected(android.widget.AdapterView<?> p,android.view.View v,int pos,long id){rotation[3]=new int[]{1,2,4,6,8,12,16,20}[pos];refresh.run();}public void onNothingSelected(android.widget.AdapterView<?> p){}});Spinner gap=option(layout,"Jarak antar pas foto",new String[]{"3 mm","0 mm","2 mm","5 mm","10 mm"});gap.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onItemSelected(android.widget.AdapterView<?> p,android.view.View v,int pos,long id){rotation[4]=new int[]{3,0,2,5,10}[pos];refresh.run();}public void onNothingSelected(android.widget.AdapterView<?> p){}});}
 TextView info=new TextView(this);layout.addView(info);info.setText("Memuat preview...");
 LinearLayout nav=new LinearLayout(this);Button prev=new Button(this),next=new Button(this);prev.setText("Sebelumnya");next.setText("Berikutnya");nav.addView(prev,new LinearLayout.LayoutParams(0,-2,1));nav.addView(next,new LinearLayout.LayoutParams(0,-2,1));if("application/pdf".equals(mime))layout.addView(nav);
 final int[] current={Math.max(0,first-1)},total={0};prev.setEnabled(false);next.setEnabled(false);
 Runnable load=()->{prev.setEnabled(false);next.setEnabled(false);int index=current[0];new Thread(()->{android.graphics.Bitmap bitmap=null;String message;int pageCount=0;
 try{if("application/pdf".equals(mime)){try(android.os.ParcelFileDescriptor fd=getContentResolver().openFileDescriptor(file,"r");android.graphics.pdf.PdfRenderer renderer=new android.graphics.pdf.PdfRenderer(fd)){int pages=renderer.getPageCount();pageCount=pages;if(index>=pages)throw new IOException("Halaman tidak tersedia");try(android.graphics.pdf.PdfRenderer.Page page=renderer.openPage(index)){float scale=Math.min(1000f/page.getWidth(),1000f/page.getHeight());bitmap=android.graphics.Bitmap.createBitmap(Math.max(1,(int)(page.getWidth()*scale)),Math.max(1,(int)(page.getHeight()*scale)),android.graphics.Bitmap.Config.ARGB_8888);bitmap.eraseColor(android.graphics.Color.WHITE);page.render(bitmap,null,null,android.graphics.pdf.PdfRenderer.Page.RENDER_MODE_FOR_DISPLAY);}message="Halaman "+(index+1)+" dari "+pages+(first>0?"; pilihan cetak "+first+"–"+last:"; semua halaman dipilih");}}
 else if(android.os.Build.VERSION.SDK_INT>=28){bitmap=android.graphics.ImageDecoder.decodeBitmap(android.graphics.ImageDecoder.createSource(getContentResolver(),file),(decoder,header,source)->{int w=header.getSize().getWidth(),h=header.getSize().getHeight();float scale=Math.min(1f,1000f/Math.max(w,h));decoder.setTargetSize(Math.max(1,(int)(w*scale)),Math.max(1,(int)(h*scale)));decoder.setAllocator(android.graphics.ImageDecoder.ALLOCATOR_SOFTWARE);});message="Preview foto; posisi cetak ditentukan printer.";}else{message="Preview JPEG memerlukan Android 9 atau lebih baru.";}}
 catch(Exception e){message="Preview gagal: "+e.getMessage();}
 android.graphics.Bitmap b=bitmap;String msg=message;int pc=pageCount;runOnUiThread(()->{total[0]=pc;if(b!=null){if("image/jpeg".equals(mime)){base[0]=b;refresh.run();}else image.setImageBitmap(b);}else image.setImageDrawable(null);info.setText(msg);prev.setEnabled(current[0]>0&&pc>0);next.setEnabled(current[0]+1<pc);});}).start();};prev.setOnClickListener(v->{if(current[0]>0){current[0]--;load.run();}});next.setOnClickListener(v->{if(current[0]+1<total[0]){current[0]++;load.run();}});load.run();ScrollView scroll=new ScrollView(this);scroll.addView(layout);return scroll;
 }
 void discover(EditText uri, TextView status){
 if(listener!=null)return;
 nsd=(android.net.nsd.NsdManager)getSystemService(NSD_SERVICE);
 listener=new android.net.nsd.NsdManager.DiscoveryListener(){
 public void onDiscoveryStarted(String t){runOnUiThread(()->status.setText("Mencari printer IPP..."));}
 public void onDiscoveryStopped(String t){}
 public void onStartDiscoveryFailed(String t,int e){runOnUiThread(()->{listener=null;status.setText("Pencarian gagal: "+e);});}
 public void onStopDiscoveryFailed(String t,int e){}
 public void onServiceLost(android.net.nsd.NsdServiceInfo s){}
 public void onServiceFound(android.net.nsd.NsdServiceInfo s){runOnUiThread(()->{if(resolving||listener==null)return;resolving=true;nsd.resolveService(s,new android.net.nsd.NsdManager.ResolveListener(){
 public void onResolveFailed(android.net.nsd.NsdServiceInfo i,int e){runOnUiThread(()->{resolving=false;status.setText("Resolusi printer gagal: "+e);});}
 public void onServiceResolved(android.net.nsd.NsdServiceInfo i){runOnUiThread(()->{resolving=false;if(listener==null||i.getHost()==null)return;try{byte[] rp=i.getAttributes().get("rp");String path=rp==null?"ipp/print":new String(rp,java.nio.charset.StandardCharsets.UTF_8);if(!path.startsWith("/"))path="/"+path;String address=new URI("ipp",null,i.getHost().getHostAddress(),i.getPort(),path,null,null).toString();uri.setText(address);status.setText("Ditemukan: "+i.getServiceName()+" — tekan Uji koneksi");stopDiscovery();}catch(Exception e){status.setText(e.toString());}});}
 });});}
 };
 try{nsd.discoverServices("_ipp._tcp.",android.net.nsd.NsdManager.PROTOCOL_DNS_SD,listener);new Handler(Looper.getMainLooper()).postDelayed(()->{if(listener!=null){stopDiscovery();status.setText("Pencarian selesai. Masukkan IP manual jika belum ditemukan.");}},15000);}catch(Exception e){listener=null;status.setText(e.toString());}
 }
 void stopDiscovery(){if(listener!=null){try{nsd.stopServiceDiscovery(listener);}catch(Exception ignored){}listener=null;}}
 @Override protected void onDestroy(){stopDiscovery();super.onDestroy();}

 Spinner option(LinearLayout l,String label,String[] values){TextView t=new TextView(this);t.setText(label);l.addView(t);Spinner s=new Spinner(this);s.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,values));l.addView(s);return s;}
 public void onCreate(Bundle b){super.onCreate(b);Ipp.cacheDirectory=getCacheDir(); LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(32,64,32,32);ScrollView scroll=new ScrollView(this);scroll.addView(l);setContentView(scroll); TextView title=new TextView(this);title.setText("IING STD Photo Print");title.setTextSize(26);title.setTextColor(0xff007f80);l.addView(title); EditText uri=new EditText(this);uri.setHint("ipp://192.168.1.100:631/ipp/print");uri.setText(getPreferences(0).getString("uri",""));l.addView(uri);Button probe=new Button(this);probe.setText("Uji koneksi printer IPP");l.addView(probe);TextView status=new TextView(this);l.addView(status);printUri=uri;printStatus=status;paper=new Spinner(this);paper.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"A4","F4 210 x 330 mm","Legal","4R"}));l.addView(paper);quality=option(l,"Kualitas",new String[]{"Default printer","Draft","Normal","High"});color=option(l,"Warna",new String[]{"Default printer","Berwarna","Hitam putih"});type=option(l,"Jenis kertas",new String[]{"Default printer","Plain paper","Glossy","Matte"});margin=option(l,"Margin semua sisi",new String[]{"Default printer","0 mm (Borderless)","3 mm","5 mm","10 mm"});scaling=option(l,"Skala cetak",new String[]{"Default printer","Fit (utuh)","Fill (dapat terpotong)","Ukuran asli"});copies=new EditText(this);copies.setInputType(2);copies.setHint("Jumlah salinan");copies.setText("1");l.addView(copies);range=new EditText(this);range.setHint("Halaman PDF (kosong = semua, contoh 2-5)");range.setSingleLine(true);l.addView(range);Button print=new Button(this);print.setText("Pilih PDF / JPEG untuk cetak");l.addView(print);print.setOnClickListener(v->{android.content.Intent i=new android.content.Intent(android.content.Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.putExtra(android.content.Intent.EXTRA_MIME_TYPES,new String[]{"application/pdf","image/jpeg"});i.addCategory(android.content.Intent.CATEGORY_OPENABLE);startActivityForResult(i,42);});Button scan=new Button(this);scan.setText("Cari printer Wi-Fi");l.addView(scan);scan.setOnClickListener(v->discover(uri,status));probe.setOnClickListener(v->{String s=uri.getText().toString().trim();getPreferences(0).edit().putString("uri",s).apply();status.setText("Memeriksa printer...");probe.setEnabled(false);new Thread(()->{String result;try{result=Ipp.probe(s);}catch(Exception e){result="Gagal: "+e.getMessage();}String r=result;runOnUiThread(()->{status.setText(r);probe.setEnabled(true);});}).start();}); }
}
